    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 37.600276, -0.784435, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-0.849723,37.599384],[-0.849692,37.599174],[-0.849621,37.599008],[-0.849573,37.599046],[-0.849501,37.599126],[-0.849385,37.599182],[-0.849299,37.59925],[-0.849198,37.599377],[-0.84914,37.59948],[-0.849125,37.599583],[-0.849126,37.599617],[-0.849125,37.59965],[-0.849243,37.599639],[-0.849572,37.599575],[-0.849723,37.599384]]],[[[-0.846149,37.596902],[-0.846106,37.596788],[-0.846049,37.596697],[-0.845977,37.596606],[-0.845891,37.596525],[-0.845819,37.596422],[-0.845747,37.596329],[-0.84569,37.596226],[-0.845633,37.596135],[-0.845575,37.596044],[-0.845489,37.59593],[-0.845388,37.595815],[-0.845273,37.595689],[-0.845159,37.595527],[-0.845072,37.595438],[-0.844972,37.595321],[-0.844871,37.595195],[-0.84477,37.595081],[-0.844656,37.594955],[-0.844526,37.594865],[-0.844382,37.594749],[-0.844239,37.594623],[-0.844138,37.594508],[-0.844037,37.594383],[-0.843937,37.594291],[-0.843822,37.594212],[-0.843693,37.594142],[-0.843549,37.594096],[-0.843405,37.594051],[-0.843261,37.593992],[-0.843145,37.593947],[-0.842987,37.593901],[-0.842786,37.593866],[-0.842656,37.593821],[-0.842498,37.59373],[-0.842426,37.59365],[-0.842369,37.593557],[-0.842398,37.593465],[-0.842456,37.593362],[-0.842499,37.593259],[-0.842542,37.593168],[-0.842672,37.593042],[-0.842788,37.59294],[-0.842903,37.592803],[-0.843018,37.592712],[-0.843076,37.592608],[-0.843076,37.592517],[-0.843063,37.592402],[-0.